import { useState } from "react";
import axios from "axios";

export default function Cadastro() {
  const [formData, setFormData] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
    foto: null,
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e) => {
    setFormData({ ...formData, foto: e.target.files[0] });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const data = new FormData();
    data.append("nome", formData.nome);
    data.append("idade", formData.idade);
    data.append("rua", formData.rua);
    data.append("bairro", formData.bairro);
    data.append("estado", formData.estado);
    data.append("biografia", formData.biografia);
    data.append("foto", formData.foto);

    try {
      await axios.post("http://localhost:3001/usuarios", data);
      alert("Usuário cadastrado com sucesso!");
    } catch (error) {
      console.error("Erro ao cadastrar:", error);
      alert("Erro ao cadastrar usuário.");
    }
  };

  return (
    <div className="container mt-5">
      <h2 className="mb-4 text-center">Cadastrar Novo Usuário</h2>
      <form onSubmit={handleSubmit} encType="multipart/form-data" className="row g-3">
        <div className="col-md-6">
          <input
            type="text"
            name="nome"
            className="form-control"
            placeholder="Nome completo"
            value={formData.nome}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-md-6">
          <input
            type="number"
            name="idade"
            className="form-control"
            placeholder="Idade"
            value={formData.idade}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-md-6">
          <input
            type="text"
            name="rua"
            className="form-control"
            placeholder="Rua"
            value={formData.rua}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-md-6">
          <input
            type="text"
            name="bairro"
            className="form-control"
            placeholder="Bairro"
            value={formData.bairro}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-md-6">
          <input
            type="text"
            name="estado"
            className="form-control"
            placeholder="Estado"
            value={formData.estado}
            onChange={handleChange}
            required
          />
        </div>
        <div className="col-12">
          <textarea
            name="biografia"
            className="form-control"
            placeholder="Biografia"
            rows="3"
            value={formData.biografia}
            onChange={handleChange}
          />
        </div>
        <div className="col-12">
          <input
            type="file"
            name="foto"
            className="form-control"
            accept="image/*"
            onChange={handleFileChange}
            required
          />
        </div>
        <div className="col-12 text-center">
          <button type="submit" className="btn btn-success mt-3">Cadastrar</button>
        </div>
      </form>
    </div>
  );
}
